{
  "description": "The creature is a quadrupedal, wolf-like animal shown in right-facing profile standing on a small patch of rocky, pebbly ground against a plain light background. Its overall shape, fur, head and paws are those of a large canid, but most of its dorsal and lateral surfaces, including the top of the head, neck, back, shoulders, hips, legs and tail, are covered in overlapping dark slate-blue to black armored plates with pale tan edges. The underside of the neck, chest, throat and parts of the legs show thick gray and white fur, while the mid-flank shows a paler segmented under-layer with rows of oval holes. The animal has a long tapering tail and four sturdy legs ending in clawed paws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "wolf-like head in right profile with a long tan muzzle, black nose, visible whiskers, a slightly open mouth, and an amber eye with a dark pupil; the forehead, crown and top of the muzzle are covered by overlapping dark plates",
      "where": "at the front right end of the body"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, triangular ears with gray-white fur inside and dark plates wrapping the outer base and edges",
      "where": "on top of the head, one more forward than the other in profile view"
    },
    {
      "part": "neck",
      "looks_like": "thick and muscular, with dense shaggy gray and white fur on the throat and underside and large overlapping dark plates on the back and sides, with pointed lower edges and pale jointed connectors between plates",
      "where": "between the head and the torso"
    },
    {
      "part": "torso",
      "looks_like": "elongated body with a straight back covered in large overlapping dark plates, pale segmented plating with rows of oval openings and small pits along the lower flank, and shaggy gray-white fur on the chest, belly and between the legs",
      "where": "central body between neck and tail, above the legs"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, jointed legs with gray fur and segmented dark plates encasing the upper and lower segments; the joints show pale, flexible skin and the plating is divided into bands around the limbs",
      "where": "two forelegs under the chest and two hind legs under the hips, supporting the body on the ground"
    },
    {
      "part": "feet",
      "looks_like": "large paw-like feet with thick toes, dark claws, and a mix of fur and small plates on the upper surface",
      "where": "at the bottom of each leg, in contact with the rocky ground"
    },
    {
      "part": "tail",
      "looks_like": "long, tapering, slightly down-curved tail fully encased in overlapping dark plates with a row of small pointed projections along the underside, ending in a narrow tip",
      "where": "extending from the rear of the torso to the left"
    },
    {
      "part": "plates",
      "looks_like": "hard, glossy, overlapping dark slate-blue to black plates with light tan rims, varying from large broad scales on the back and shoulders to smaller banded segments on the legs and tail and spiky-edged plates on the neck and tail underside; the flank under-plates are paler with regular oval holes",
      "where": "covering the top of the head, ears base, dorsal neck, back, sides, shoulders, hips, outer legs and entire tail"
    },
    {
      "part": "fur/markings",
      "looks_like": "thick, shaggy fur in shades of gray, white and light tan on the muzzle, cheeks, throat, chest, belly, inner legs and ear interiors, with darker gray on the back of the neck and sides",
      "where": "on the face, underside of neck and body, and exposed parts of the legs and paws between plates"
    }
  ],
  "attached_objects": [],
  "animals": [
    "wolf",
    "armadillo",
    "isopod"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
